?", "a": ["Cocher « Première page différente »", "Supprimer la première page entière", "Changer la police de l’en-tête", "Réduire la marge du haut à zéro"], "e": "C’est une option des outils d’en-tête et de pied de page."}, {"level": "level-bureau-word-format", "q": "Quel contenu est typique d’un pied de page ?", "a": ["Le numéro de page et le nom du document", "Le titre du chapitre en grand", "La table des matières", "Une image de fond"], "e": "Ces éléments se répètent à chaque page."}, {"level": "level-bureau-word-format", "q": "Que se passe-t-il quand on modifie l’en-tête d’une section liée à la précédente ?", "a": ["La modification s’applique aux sections liées", "Rien ne change", "Le document est supprimé", "Seule la page courante change"], "e": "On peut dissocier avec « Lier au précédent »."}, {"level": "level-bureau-word-format", "q": "Que faut-il appliquer pour générer une table des matières automatique ?", "a": ["Des styles de titre", "Des puces", "Un saut de page après chaque ligne", "Une police unique"], "e": "Word construit la table à partir des titres."}, {"level": "level-bureau-word-format", "q": "Comment mettre à jour la table des matières après des modifications ?", "a": ["Clic droit > Mettre à jour les champs", "La réécrire à la main", "Supprimer le document", "Changer la police"], "e": "On peut actualiser les numéros de page seuls ou la table entière."}, {"level": "level-bureau-word-format", "q": "À quoi sert le volet Navigation ?", "a": ["À parcourir le document par titres", "À corriger l’orthographe du texte", "À imprimer plusieurs copies", "À insérer des images dans le texte"], "e": "Il s’ouvre depuis l’onglet Affichage."}, {"level": "level-bureau-word-format", "q": "À quoi sert un signet ?", "a": ["À marquer un emplacement", "À protéger le document entier", "À trier les lignes d’un tableau", "À changer la langue du texte"], "e": "Insertion > Signet."}, {"level": "level-bureau-word-format", "q": "Que permet la légende d’une image ?", "a": ["Numéroter les figures", "Compresser l’image sans perte", "Rogner les bords de l’image", "Changer les couleurs"], "e": "Références > Insérer une légende."}, {"level": "level-bureau-word-format", "q": "À quoi sert le suivi des modifications ?", "a": ["À voir qui a modifié quoi dans un document", "À supprimer les erreurs seules", "À imprimer en couleur", "À protéger par mot de passe"], "e": "Les ajouts et suppressions apparaissent en couleur."}, {"level": "level-bureau-word-format", "q": "Que permet un commentaire ?", "a": ["Annoter le texte dans la marge", "Supprimer le texte sélectionné", "Traduire tout le document", "Insérer une image dans la marge"], "e": "Utile pour échanger avec un relecteur."}, {"level": "level-bureau-word-format", "q": "Que fait « Accepter » une modification suivie ?", "a": ["Elle l’intègre définitivement au texte", "Elle supprime le commentaire seulement", "Elle ferme le document", "Elle imprime la page"], "e": "« Refuser » rétablit le texte d’origine."}, {"level": "level-bureau-word-format", "q": "Que souligne le correcteur d’orthographe et de grammaire ?", "a": ["Les fautes possibles", "Le contenu des images insérées", "La taille du fichier enregistré", "La mise en page des tableaux"], "e": "Une relecture personnelle reste indispensable."}, {"level": "level-bureau-word-format", "q": "Quelle fonction compte les mots d’un document ?", "a": ["Révision > Nombre de mots", "Insertion > Forme", "Accueil > Police", "Affichage > Zoom"], "e": "Le compteur s’affiche aussi en bas de la fenêtre."}, {"level": "level-bureau-word-format", "q": "À quoi sert le publipostage ?", "a": ["À personnaliser des courriers en série", "À traduire un document entier", "À compresser toutes les images", "À trier les lignes d’un tableau"], "e": "Par exemple des lettres adressées à plusieurs personnes."}, {"level": "level-bureau-word-format", "q": "Que contient généralement la source de données d’un publipostage ?", "a": ["Une liste de destinataires (nom, adresse)", "Les images du document", "La table des matières", "Les styles"], "e": "Un tableau Excel est une source courante."}, {"level": "level-bureau-word-format", "q": "Quel est l’intérêt d’un modèle de document (.dotx) ?", "a": ["Réutiliser mise en page et styles", "Réduire la taille du fichier à zéro", "Protéger le fichier contre les virus", "Convertir automatiquement en PDF"], "e": "Le modèle sert de point de départ."}, {"level": "level-bureau-word-format", "q": "Comment exporter un document en PDF ?", "a": ["Fichier > Exporter > PDF", "Accueil > Police > Exporter le texte", "Insertion > Tableau > Convertir", "Affichage > Zoom > Page entière"], "e": "On peut aussi passer par Enregistrer sous."}, {"level": "level-bureau-word-format", "q": "Quelle précaution prendre avant de partager un document ?", "a": ["Retirer commentaires et suivi", "Changer la police du texte", "Supprimer toutes les marges du document", "Augmenter la taille du texte"], "e": "Un document partagé peut contenir des informations internes."}, {"level": "level-bureau-excel-fond", "q": "Comment s’appelle l’intersection d’une colonne et d’une ligne ?", "a": ["Une cellule", "Une plage", "Une feuille", "Un classeur"], "e": "Exemple : B3."}, {"level": "level-bureau-excel-fond", "q": "Que désigne la référence B3 ?", "a": ["La colonne B, ligne 3", "La ligne B, colonne 3", "La feuille nommée B3", "Le classeur nommé B3"], "e": "La lettre indique la colonne, le chiffre la ligne."}, {"level": "level-bureau-excel-fond", "q": "Que désigne A1:C3 ?", "a": ["Une plage de 9 cellules", "Une seule cellule", "Une feuille", "Un graphique"], "e": "Trois colonnes sur trois lignes."}, {"level": "level-bureau-excel-fond", "q": "Comment ajouter une feuille de calcul ?", "a": ["Cliquer sur + près des onglets", "Appuyer sur Suppr deux fois", "Fermer puis rouvrir le classeur", "Changer la police des onglets"], "e": "On peut la renommer par double-clic."}, {"level": "level-bureau-excel-fond", "q": "Quelle extension a un classeur Excel récent ?", "a": [".xlsx", ".docx", ".pptx", ".txt"], "e": "Le format .xls est l’ancien."}, {"level": "level-bureau-excel-fond", "q": "Comment Excel aligne-t-il un nombre par défaut ?", "a": ["À droite", "À gauche", "Au centre", "En haut"], "e": "Le texte est aligné à gauche."}, {"level": "level-bureau-excel-fond", "q": "Que signifie ####### dans une cellule ?", "a": ["Colonne trop étroite", "La formule contient une erreur", "Le fichier est corrompu", "La feuille est protégée"], "e": "Il suffit d’élargir la colonne."}, {"level": "level-bureau-excel-fond", "q": "Quelle touche annule une saisie en cours dans une cellule ?", "a": ["Échap", "Entrée", "Tab", "F2"], "e": "Entrée valide la saisie."}, {"level": "level-bureau-excel-fond", "q": "Comment saisir une date reconnue comme telle ?", "a": ["Avec un format jj/mm/aaaa", "Avec des lettres seulement", "Avec des guillemets", "Avec un point d’exclamation"], "e": "Excel peut alors calculer avec les dates."}, {"level": "level-bureau-excel-fond", "q": "Quelle touche permet de modifier le contenu d’une cellule sans le retaper ?", "a": ["F2", "F5", "F7", "F11"], "e": "F2 active le mode édition."}, {"level": "level-bureau-excel-fond", "q": "Quel format affiche 0,15 sous la forme 15 % ?", "a": ["Pourcentage", "Monétaire", "Date", "Texte"], "e": "Le format ne change pas la valeur stockée."}, {"level": "level-bureau-excel-fond", "q": "Que fait « Fusionner et centrer » ?", "a": ["Elle regroupe des cellules et centre le contenu", "Elle trie les cellules", "Elle supprime des cellules", "Elle protège des cellules"], "e": "À éviter dans une zone de données à trier."}, {"level": "level-bureau-excel-fond", "q": "À quoi sert « Renvoyer à la ligne automatiquement » ?", "a": ["Afficher le texte sur plusieurs lignes", "Supprimer le texte trop long", "Fusionner les cellules voisines", "Figer la première ligne"], "e": "La hauteur de la ligne s’adapte."}, {"level": "level-bureau-excel-fond", "q": "Quel outil copie la mise en forme d’une cellule vers d’autres ?", "a": ["Reproduire la mise en forme", "Remplissage instantané", "Tri personnalisé", "Figer les volets"], "e": "Le pinceau reprend la mise en forme."}, {"level": "level-bureau-excel-fond", "q": "Quel format affiche un montant avec le symbole de la monnaie ?", "a": ["Monétaire", "Texte", "Date", "Scientifique"], "e": "Le nombre de décimales reste réglable."}, {"level": "level-bureau-excel-fond", "q": "Comment élargir une colonne automatiquement à son contenu ?", "a": ["Double-clic sur la limite de colonne", "Appuyer sur Suppr", "Changer la police", "Cliquer sur la ligne"], "e": "Double-clic sur le bord droit de l’en-tête."}, {"level": "level-bureau-excel-fond", "q": "Que fait la poignée de recopie (petit carré en bas à droite de la cellule) ?", "a": ["Elle recopie ou prolonge une série", "Elle supprime la cellule choisie", "Elle trie toute la colonne", "Elle protège la feuille entière"], "e": "Taper 1 et 2 puis recopier prolonge la série."}, {"level": "level-bureau-excel-fond", "q": "Comment insérer une ligne entre deux lignes ?", "a": ["Clic droit sur la ligne > Insérer", "Appuyer sur Suppr", "Fusionner deux cellules", "Trier les données"], "e": "La nouvelle ligne se place au-dessus."}, {"level": "level-bureau-excel-fond", "q": "Que fait « Figer les volets » ?", "a": ["Garder des lignes visibles", "Protéger toutes les formules", "Supprimer les lignes vides", "Trier les lignes du tableau"], "e": "Pratique pour garder les en-têtes visibles."}, {"level": "level-bureau-excel-fond", "q": "Que se passe-t-il quand on masque une colonne ?", "a": ["Elle n’est plus affichée mais ses données existent toujours", "Ses données sont supprimées", "Elle est protégée par mot de passe", "Elle est fusionnée avec la voisine"], "e": "Afficher la colonne la fait réapparaître."}, {"level": "level-bureau-excel-fond", "q": "Quel est le rôle d’un filtre ?", "a": ["Afficher les lignes selon un critère", "Supprimer les lignes inutiles", "Fusionner des cellules voisines", "Protéger la feuille de calcul"], "e": "Les lignes masquées ne sont pas supprimées."}, {"level": "level-bureau-excel-fond", "q": "Que fait un tri croissant sur des nombres ?", "a": ["Il classe du plus petit au plus grand", "Il classe du plus grand au plus petit", "Il supprime les doublons", "Il additionne les valeurs"], "e": "Le tri décroissant fait l’inverse."}, {"level": "level-bureau-excel-fond", "q": "Pourquoi sélectionner tout le tableau avant de trier ?", "a": ["Garder les lignes cohérentes", "Changer la police du tableau", "Fusionner les colonnes entre elles", "Protéger les cellules triées"], "e": "Trier une seule colonne désolidariserait les données."}, {"level": "level-bureau-excel-fond", "q": "Comment activer les filtres d’un tableau ?", "a": ["Données > Filtrer", "Insertion > Forme", "Accueil > Police", "Révision > Commentaire"], "e": "Des flèches apparaissent dans les en-têtes."}, {"level": "level-bureau-excel-fond", "q": "Que fait « Supprimer les doublons » ?", "a": ["Elle retire les lignes identiques", "Elle trie le tableau", "Elle fusionne les cellules", "Elle protège la feuille"], "e": "À utiliser avec précaution : les lignes retirées disparaissent."}, {"level": "level-bureau-excel-fond", "q": "Quel graphique convient pour comparer des quantités entre catégories ?", "a": ["L’histogramme (colonnes)", "Le secteur découpé en dix parts", "Le nuage de points sans axes", "Aucun graphique"], "e": "Les colonnes comparent facilement des valeurs."}, {"level": "level-bureau-excel-fond", "q": "Quel graphique montre une évolution dans le temps ?", "a": ["La courbe", "Le secteur", "Le radar", "La carte"], "e": "La courbe montre une tendance."}, {"level": "level-bureau-excel-fond", "q": "Quel graphique représente les parts d’un total ?", "a": ["Le secteur (camembert)", "La courbe", "Le nuage de points", "La surface"], "e": "Il convient avec peu de catégories."}, {"level": "level-bureau-excel-fond", "q": "Que faut-il ajouter pour qu’un graphique soit compréhensible ?", "a": ["Un titre et des axes nommés", "Davantage de couleurs vives", "Une image décorative en fond", "Un effet 3D sur les barres"], "e": "La lisibilité prime sur la décoration."}, {"level": "level-bureau-excel-fond", "q": "Quelle sélection permet de créer un graphique ?", "a": ["Les cellules de données avec leurs en-têtes", "Une cellule vide", "La feuille entière sans données", "Seulement le titre"], "e": "Excel déduit les séries à partir de la sélection."}, {"level": "level-bureau-excel-fond", "q": "À quoi sert la zone d’impression ?", "a": ["Imprimer seulement la partie choisie", "Fusionner les cellules", "Protéger la feuille", "Trier les données"], "e": "Utile pour éviter d’imprimer toute la feuille."}, {"level": "level-bureau-excel-fond", "q": "Comment imprimer un tableau sur une seule page de large ?", "a": ["Ajuster toutes les colonnes sur une page", "Supprimer des colonnes au hasard", "Changer la police du tableau entier", "Fusionner toutes les colonnes entre elles"], "e": "C’est une option de la fenêtre d’impression."}, {"level": "level-bureau-excel-fond", "q": "À quoi sert la répétition des titres à l’impression ?", "a": ["Répéter l’en-tête sur chaque page", "Imprimer le classeur en couleur", "Supprimer automatiquement les doublons", "Trier les lignes imprimées"], "e": "Mise en page > Titres à imprimer."}, {"level": "level-bureau-excel-fond", "q": "Quel format léger est lisible par presque tous les tableurs ?", "a": ["CSV", "PPTX", "DOCX", "PSD"], "e": "Le CSV stocke des valeurs séparées par des virgules ou des points-virgules."}, {"level": "level-bureau-excel-fond", "q": "Que faut-il vérifier avant d’envoyer un classeur ?", "a": ["Absence de données masquées sensibles", "Que la police est élégante", "Que les couleurs sont assez vives", "Que les colonnes sont toutes fusionnées"], "e": "Les feuilles et colonnes masquées restent dans le fichier."}, {"level": "level-bureau-excel-formules", "q": "Avec quel signe commence une formule ?", "a": ["=", "+", "#", "@"], "e": "Sans le signe égal, Excel lit du texte."}, {"level": "level-bureau-excel-formules", "q": "Que renvoie =2+3*4 ?", "a": ["14", "20", "24", "9"], "e": "La multiplication est prioritaire sur l’addition."}, {"level": "level-bureau-excel-formules", "q": "Que renvoie =(2+3)*4 ?", "a": ["20", "14", "24", "9"], "e": "Les parenthèses sont prioritaires."}, {"level": "level-bureau-excel-formules", "q": "Quel opérateur calcule une puissance ?", "a": ["^", "*", "%", "&"], "e": "=2^3 donne 8."}, {"level": "level-bureau-excel-formules", "q": "Que renvoie =\"Bon\"&\"jour\" ?", "a": ["Bonjour", "Bon jour", "Bon&jour", "#NOM?"], "e": "L’opérateur & concatène du texte."}, {"level": "level-bureau-excel-formules", "q": "Si A1=12, A2=8, A3=15, A4=5, que renvoie =SOMME(A1:A4) ?", "a": ["40", "10", "5", "15"], "e": "SOMME s’applique à la plage A1:A4."}, {"level": "level-bureau-excel-formules", "q": "Si A1=10, A2=14, A3=6, A4=10, que renvoie =MOYENNE(A1:A4) ?", "a": ["10", "40", "6", "14"], "e": "MOYENNE s’applique à la plage A1:A4."}, {"level": "level-bureau-excel-formules", "q": "Si A1=7, A2=23, A3=18, A4=4, que renvoie =MAX(A1:A4) ?", "a": ["23", "52", "13", "4"], "e": "MAX s’applique à la plage A1:A4."}, {"level": "level-bureau-excel-formules", "q": "Si A1=9, A2=3, A3=14, A4=6, que renvoie =MIN(A1:A4) ?", "a": ["3", "32", "8", "14"], "e": "MIN s’applique à la plage A1:A4."}, {"level": "level-bureau-excel-formules", "q": "Si A1=5, A2=8, A3=2, A4=9, A5=1, que renvoie =NB(A1:A5) ?", "a": ["5", "25", "1", "9"], "e": "NB s’applique à la plage A1:A5."}, {"level": "level-bureau-excel-formules", "q": "Si A1 contient 12, que renvoie =SI(A1>=10;\"Admis\";\"Refusé\") ?", "a": ["Admis", "Refusé", "VRAI", "12"], "e": "12 dépasse le seuil de 10."}, {"level": "level-bureau-excel-formules", "q": "Si A1 contient 7, que renvoie =SI(A1>=10;\"Admis\";\"Refusé\") ?", "a": ["Refusé", "Admis", "FAUX", "7"], "e": "7 est inférieur à 10."}, {"level": "level-bureau-excel-formules", "q": "Quel séparateur d’arguments utilise Excel en français ?", "a": ["Le point-virgule", "La virgule", "Le deux-points", "Le tiret"], "e": "Exemple : =SI(A1>0;1;0)."}, {"level": "level-bureau-excel-formules", "q": "Que renvoie =ET(5>3;2>4) ?", "a": ["FAUX", "VRAI", "5", "#VALEUR!"], "e": "ET est vrai seulement si toutes les conditions sont vraies."}, {"level": "level-bureau-excel-formules", "q": "Que renvoie =OU(5>3;2>4) ?", "a": ["VRAI", "FAUX", "5", "#NOM?"], "e": "OU est vrai si au moins une condition est vraie."}, {"level": "level-bureau-excel-formules", "q": "Que devient =A1*B1 saisie en C1 si on la recopie en C2 ?", "a": ["=A2*B2", "=A1*B1", "=A2*B1", "=A1*B2"], "e": "Les références relatives suivent le déplacement."}, {"level": "level-bureau-excel-formules", "q": "Quel signe fixe une référence de cellule ?", "a": ["$", "#", "&", "@"], "e": "=$A$1 reste A1 après recopie."}, {"level": "level-bureau-excel-formules", "q": "Que devient =$A$1*B1 saisie en C1 si on la recopie en C2 ?", "a": ["=$A$1*B2", "=A2*B2", "=$A$1*B1", "=A$1*B2"], "e": "$A$1 est absolue, B1 est relative."}, {"level": "level-bureau-excel-formules", "q": "Que fixe la référence A$1 ?", "a": ["La ligne seulement", "La colonne seulement", "La colonne et la ligne", "Rien"], "e": "On parle de référence mixte."}, {"level": "level-bureau-excel-formules", "q": "Quelle touche bascule entre références relatives et absolues pendant la saisie ?", "a": ["F4", "F2", "F5", "F9"], "e": "Chaque appui sur F4 change la position des signes $."}, {"level": "level-bureau-excel-formules", "q": "Dans une plage (catégorie = valeur) : Pain = 300; Riz = 500; Pain = 450; Thé = 200. Que renvoie SOMME.SI(catégories; \"Pain\"; valeurs) ?", "a": ["750", "1450", "4", "760"], "e": "SOMME.SI ne retient que les lignes égales à « Pain »."}, {"level": "level-bureau-excel-formules", "q": "Dans une plage (catégorie = valeur) : A = 1; B = 2; A = 3; A = 4; C = 5. Que renvoie NB.SI(catégories; \"A\") ?", "a": ["3", "15", "5", "13"], "e": "NB.SI ne retient que les lignes égales à « A »."}, {"level": "level-bureau-excel-formules", "q": "Dans une plage (catégorie = valeur) : Nord = 120; Sud = 80; Nord = 60; Est = 90. Que renvoie SOMME.SI(catégories; \"Nord\"; valeurs) ?", "a": ["180", "350", "4", "190"], "e": "SOMME.SI ne retient que les lignes égales à « Nord »."}, {"level": "level-bureau-excel-formules", "q": "Quelle fonction compte les cellules d’une plage qui respectent un critère ?", "a": ["NB.SI", "NB", "SOMME", "MOYENNE"], "e": "NB compte seulement les cellules numériques."}, {"level": "level-bureau-excel-formules", "q": "À quoi sert RECHERCHEV ?", "a": ["À chercher une valeur dans la première colonne d’un tableau et renvoyer une valeur de la même ligne", "À trier un tableau", "À créer un graphique", "À protéger une feuille"], "e": "Le dernier argument règle la correspondance exacte ou approchée."}, {"level": "level-bureau-excel-formules", "q": "Que signifie #DIV/0! ?", "a": ["Division par zéro", "Nom de fonction inconnu", "Référence supprimée", "Type de valeur incorrect"], "e": "Par exemple =A1/B1 avec B1 égal à 0."}, {"level": "level-bureau-excel-formules", "q": "Que signifie #NOM? ?", "a": ["Excel ne reconnaît pas un nom de fonction ou de cellule", "Division par zéro", "Colonne trop étroite", "Valeur introuvable"], "e": "C’est souvent une faute de frappe dans la fonction."}, {"level": "level-bureau-excel-formules", "q": "Que signifie #REF! ?", "a": ["Une référence n’existe plus", "Division par zéro", "Nom inconnu", "Colonne trop étroite"], "e": "Cela arrive après la suppression d’une cellule référencée."}, {"level": "level-bureau-excel-formules", "q": "Que signifie #VALEUR! ?", "a": ["Un opérande est d’un type incorrect (du texte dans un calcul)", "Division par zéro", "Référence supprimée", "Colonne trop étroite"], "e": "Par exemple =A1+B1 avec du texte en A1."}, {"level": "level-bureau-excel-formules", "q": "Quel outil aide à comprendre l’origine d’une erreur dans une formule ?", "a": ["Évaluation de formule", "Tri personnalisé", "Filtre", "Zone d’impression"], "e": "Elle exécute la formule pas à pas."}, {"level": "level-bureau-excel-formules", "q": "À quoi sert un tableau croisé dynamique ?", "a": ["À synthétiser et regrouper de gros volumes de données", "À rédiger du texte", "À imprimer", "À retoucher des images"], "e": "Il calcule des totaux par catégorie."}, {"level": "level-bureau-excel-formules", "q": "Que faire quand les données sources d’un tableau croisé ont changé ?", "a": ["Actualiser le tableau croisé", "Le recréer systématiquement", "Supprimer la feuille", "Changer la police"], "e": "Données > Actualiser tout."}, {"level": "level-bureau-excel-formules", "q": "À quoi sert la validation des données ?", "a": ["À limiter ce qui peut être saisi dans une cellule", "À corriger l’orthographe", "À trier", "À fusionner"], "e": "Par exemple une liste déroulante."}, {"level": "level-bureau-excel-formules", "q": "À quoi sert la mise en forme conditionnelle ?", "a": ["À changer l’aspect d’une cellule selon sa valeur", "À protéger la feuille", "À créer des liens", "À imprimer plus vite"], "e": "Par exemple surligner en rouge les valeurs négatives."}, {"level": "level-bureau-excel-formules", "q": "Quel est l’avantage d’un tableau Excel (Ctrl + T) ?", "a": ["Formules et mise en forme s’étendent aux nouvelles lignes", "Il supprime les doublons", "Il imprime en couleur", "Il protège les données"], "e": "Il propose aussi filtres et noms de colonnes."}, {"level": "level-bureau-powerpoint", "q": "Quel est le rôle d’une disposition de diapositive ?", "a": ["Placer titre, texte et images", "Changer la police du système", "Compresser le fichier au maximum", "Protéger la présentation entière"], "e": "Exemples : Titre, Titre et contenu, Deux contenus."}, {"level": "level-bureau-powerpoint", "q": "Que fait un thème ?", "a": ["Applique des couleurs, polices et arrière-plans cohérents", "Ajoute des animations automatiquement", "Supprime les images", "Trie les diapositives"], "e": "Le thème donne une unité visuelle."}, {"level": "level-bureau-powerpoint", "q": "Quel est l’avantage de la Trieuse de diapositives ?", "a": ["Réordonner les diapositives", "Modifier les polices du thème", "Corriger l’orthographe de toutes les pages", "Imprimer les diapositives en série"], "e": "Un glisser-déposer suffit."}, {"level": "level-bureau-powerpoint", "q": "Quel raccourci insère une nouvelle diapositive ?", "a": ["Ctrl + M", "Ctrl + N", "Ctrl + D", "Ctrl + L"], "e": "Ctrl + N crée une nouvelle présentation."}, {"level": "level-bureau-powerpoint", "q": "Quelle extension a une présentation PowerPoint récente ?", "a": [".pptx", ".docx", ".xlsx", ".txt"], "e": "Le format .ppsx s’ouvre directement en diaporama."}, {"level": "level-bureau-powerpoint", "q": "Quelle règle de conception améliore la lisibilité ?", "a": ["Peu de texte par diapositive, une idée principale", "Un maximum de texte", "Une police différente par diapositive", "Des couleurs vives partout"], "e": "Une idée par diapositive."}, {"level": "level-bureau-powerpoint", "q": "Quelle taille de texte minimale reste lisible dans une salle ?", "a": ["Environ 24 points", "10 points, au plus", "6 points, pour tout loger", "8 points, comme un livre"], "e": "Plus le public est loin, plus les caractères doivent être gros."}, {"level": "level-bureau-powerpoint", "q": "Quel contraste faut-il privilégier ?", "a": ["Texte foncé sur fond clair, ou l’inverse", "Texte jaune sur fond blanc", "Texte gris clair sur fond blanc", "Texte rouge sur fond vert"], "e": "Un bon contraste facilite la lecture."}, {"level": "level-bureau-powerpoint", "q": "Que faut-il éviter sur une diapositive ?", "a": ["Un long texte lu à voix haute", "Une image pertinente et nette", "Un titre clair et court", "Une liste de trois points"], "e": "Mieux vaut résumer à l’écrit et développer à l’oral."}, {"level": "level-bureau-powerpoint", "q": "Combien de polices différentes recommande-t-on au maximum ?", "a": ["Deux", "Cinq", "Dix", "Une par diapositive"], "e": "Une pour les titres, une pour le texte."}, {"level": "level-bureau-powerpoint", "q": "À quoi sert un SmartArt ?", "a": ["À illustrer une liste ou un processus", "À corriger l’orthographe du titre", "À protéger le fichier contre la copie", "À imprimer en grand format"], "e": "Organigrammes, cycles, étapes."}, {"level": "level-bureau-powerpoint", "q": "Quelle poignée garde les proportions d’une image ?", "a": ["Une poignée d’angle", "Une poignée du milieu d’un côté", "La poignée de rotation", "Le point jaune de réglage"], "e": "Les poignées d’angle conservent le rapport largeur/hauteur."}, {"level": "level-bureau-powerpoint", "q": "Quel outil aligne plusieurs objets entre eux ?", "a": ["Aligner (onglet Format)", "Ombre", "Rogner", "Reproduire la mise en forme"], "e": "Aligner et répartir donnent une mise en page propre."}, {"level": "level-bureau-powerpoint", "q": "Quel est l’intérêt d’un graphique dans une présentation ?", "a": ["Faire comprendre des chiffres d’un coup d’œil", "Remplacer la voix du présentateur", "Alléger le fichier", "Supprimer le texte"], "e": "Il doit rester simple."}, {"level": "level-bureau-powerpoint", "q": "Que faut-il vérifier pour une image téléchargée ?", "a": ["Qu’on a le droit de l’utiliser", "Qu’elle est la plus grande possible", "Qu’elle est en noir et blanc", "Qu’elle porte un nom court"], "e": "Il faut respecter les droits d’auteur."}, {"level": "level-bureau-powerpoint", "q": "À quoi sert le masque des diapositives ?", "a": ["Régler la mise en forme commune", "Masquer une diapositive précise", "Protéger le fichier par mot de passe", "Trier les diapositives par titre"], "e": "Affichage > Masque des diapositives."}, {"level": "level-bureau-powerpoint", "q": "Où place-t-on un logo qui doit apparaître sur toutes les diapositives ?", "a": ["Dans le masque des diapositives", "Sur chaque diapositive à la main", "Dans les notes", "Dans la trieuse"], "e": "Une modification du masque se répercute partout."}, {"level": "level-bureau-powerpoint", "q": "Que se passe-t-il quand on change la police dans le masque ?", "a": ["Elle change pour toutes les diapositives concernées", "Rien ne change", "Seule la première diapositive change", "Le fichier est supprimé"], "e": "Les dispositions héritent du masque."}, {"level": "level-bureau-powerpoint", "q": "Pourquoi numéroter les diapositives ?", "a": ["Se repérer pendant les questions", "Réduire le poids du fichier", "Changer le thème de couleurs", "Animer automatiquement le texte"], "e": "Insertion > Numéro de diapositive."}, {"level": "level-bureau-powerpoint", "q": "Que permet l’option « Pied de page » ?", "a": ["Répéter un texte en bas de page", "Insérer une vidéo en bas", "Changer l’orientation du diaporama", "Trier les diapositives par date"], "e": "Par exemple le nom de l’organisme."}, {"level": "level-bureau-powerpoint", "q": "Quelle différence y a-t-il entre animation et transition ?", "a": ["La transition concerne le passage entre diapositives, l’animation concerne un objet", "Il n’y en a aucune", "L’animation concerne le passage entre diapositives", "La transition concerne un objet"], "e": "Chacune a son onglet dans le ruban."}, {"level": "level-bureau-powerpoint", "q": "Que faut-il privilégier dans les animations ?", "a": ["La sobriété", "Un maximum d’effets", "Des sons à chaque clic", "Un effet différent par objet"], "e": "Trop d’effets distraient le public."}, {"level": "level-bureau-powerpoint", "q": "Quel déclencheur fait apparaître un objet à chaque clic de souris ?", "a": ["Au clic", "Avec la précédente", "Après la précédente", "Au démarrage automatique"], "e": "Les autres déclencheurs enchaînent sans clic."}, {"level": "level-bureau-powerpoint", "q": "À quoi sert le volet Animation ?", "a": ["À gérer l’ordre et le minutage des animations", "À corriger l’orthographe", "À protéger la présentation", "À imprimer"], "e": "Il permet de réordonner les effets."}, {"level": "level-bureau-powerpoint", "q": "Quelle transition convient à une présentation professionnelle ?", "a": ["Une transition discrète comme le fondu", "Une transition tournante spectaculaire", "Un effet différent entre chaque diapositive", "Des sons de transition"], "e": "La sobriété renforce le message."}, {"level": "level-bureau-powerpoint", "q": "Quelle touche lance le diaporama depuis le début ?", "a": ["F5", "F2", "F7", "F11"], "e": "Maj + F5 le lance depuis la diapositive en cours."}, {"level": "level-bureau-powerpoint", "q": "Quelle touche quitte le diaporama ?", "a": ["Échap", "F5", "Tab", "Suppr"], "e": "Échap ramène à l’édition."}, {"level": "level-bureau-powerpoint", "q": "À quoi servent les notes du présentateur ?", "a": ["À préparer son discours", "À protéger le fichier entier", "À modifier le thème graphique", "À insérer des images animées"], "e": "Elles s’affichent en mode présentateur."}, {"level": "level-bureau-powerpoint", "q": "Que permet le mode présentateur ?", "a": ["Voir ses notes et la suite", "Imprimer les diapositives plus vite", "Modifier le thème en direct", "Compresser les images du fichier"], "e": "Il utilise deux écrans."}, {"level": "level-bureau-powerpoint", "q": "Que faire avant la présentation pour éviter les surprises techniques ?", "a": ["Répéter sur le matériel final", "Ajouter davantage d’animations", "Agrandir la taille de l’écran", "Fermer le fichier et attendre"], "e": "Un test évite les problèmes de projection."}, {"level": "level-bureau-powerpoint", "q": "Comment exporter une présentation en PDF ?", "a": ["Fichier > Exporter > PDF", "Accueil > Police > Exporter", "Insertion > Forme > Convertir", "Affichage > Zoom > Plein écran"], "e": "Le PDF conserve l’apparence."}, {"level": "level-bureau-powerpoint", "q": "Quel format lance directement le diaporama à l’ouverture ?", "a": [".ppsx", ".pptx", ".docx", ".xlsx"], "e": "Un fichier .ppsx s’ouvre en mode diaporama."}, {"level": "level-bureau-powerpoint", "q": "Que permet l’impression en « documents » ?", "a": ["Imprimer plusieurs diapositives par page", "Modifier les an